  static const cardPadding = EdgeInsets.fromLTRB(16, 18, 16, 18);

  static BoxDecoration box({
    required Color bg,
    required Color br,
  }) {
    return BoxDecoration(
      color: bg,
      borderRadius: BorderRadius.circular(radius),
      border: Border.all(color: br, width: 1),
    );
  }
}

