    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // 問題
        ExplanationBlock(
          title: '問題',
          body: question,
        ),
        const SizedBox(height: 20),

        // 選択肢
        Text('選択肢', style: theme.textTheme.titleMedium),
        const SizedBox(height: 8),
        ...orderedKeys.map((label) {
          final text = choices[label] ?? '';
          final userSelected = sel.contains(label);
          final isCorrect = cor.contains(label);

          ChoiceTileState state = ChoiceTileState.normal;
          if (userSelected && isCorrect) {
            state = ChoiceTileState.correct;
          } else if (userSelected && !isCorrect) {
            state = ChoiceTileState.incorrect;
          } else if (!userSelected && isCorrect) {
            state = ChoiceTileState.correct;
          }

          return Padding(
            padding: const EdgeInsets.only(bottom: 8),
            child: ChoiceTile(
              label: label,
              text: text,
              state: state,
              dense: true,
            ),
          );
        }),

        const SizedBox(height: 20),

        // 解答の一文
        _answerLine(context, isIncorrect, correctCount, cor),

        const SizedBox(height: 8),

        // 解説
        if (explanation.trim().isNotEmpty) ...[
          ExplanationBlock(
            title: '解説',
            body: explanation.trim(),
          ),
          const SizedBox(height: 20),
        ],

        // 根拠
        if (rationales != null && rationales!.isNotEmpty) ...[
          Text('根拠', style: theme.textTheme.titleMedium),
          const SizedBox(height: 8),
          ..._rationaleTiles(orderedKeys, cor),
        ],
      ],
    );
  }

  /// 「解答：A と D（2つ）」の行
  Widget _answerLine(BuildContext context, bool isIncorrect, int count, Set<String> cor) {
    final theme = Theme.of(context);
    final list = _labelsToJoined(cor.toList()..sort());
    final suffix = count >= 2 ? '（${count}つ）' : '';
    final head = isIncorrect ? '解答（誤っているもの）' : '解答';
    return Text(
      '$head：$list$suffix',
      style: theme.textTheme.bodyLarge?.copyWith(fontWeight: FontWeight.w600),
    );
  }

  /// 根拠のタイル群（ChoiceTile で正誤色を合わせる）
  List<Widget> _rationaleTiles(List<String> orderedKeys, Set<String> cor) {
    final items = <Widget>[];
    for (final k in orderedKeys) {
      final txt = rationales?[k]?.trim() ?? '';
      if (txt.isEmpty) continue;
      final isCorrect = cor.contains(k);
      items.add(
        Padding(
          padding: const EdgeInsets.only(bottom: 8),
          child: ChoiceTile(
            label: k,
            text: txt,
            state: isCorrect ? ChoiceTileState.correct : ChoiceTileState.incorrect,
            dense: true,
          ),
        ),
      );
    }
    return items;
  }

  /// ['A','C','D'] -> 'A と C と D'
  String _labelsToJoined(List<String> labels) {
    if (labels.isEmpty) return '';
    if (labels.length == 1) return labels.first;
    return [
      ...labels.sublist(0, labels.length - 1).map((e) => e),
      'と ${labels.last}'
    ].join(' ');
  }
}

// lib/widgets/score_chart_panel.dart
import 'package:flutter/material.dart';

import '../models/answer_history.dart';      // AnswerHistory / AnswerRecord（既存）
import '../models/history_models.dart';      // HistoryRecord / DomainSummary（新モデル）
import '../services/history_stats.dart';     // 集計ロジック
import 'history_charts.dart';                // MiniBarChart / buildBarItemsFromDomainSummaries

/// 成績画面など“どこにでも”置ける、分野別正答率の棒グラフパネル。
/// 画面側は `const ScoreChartPanel()` を配置するだけでOK。
class ScoreChartPanel extends StatelessWidget {
  final String title;
  final int maxItems;

  const ScoreChartPanel({
    super.key,
    this.title = '分野別の正答率',
    this.maxItems = 6,
  });

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<List<AnswerRecord>>(
      future: AnswerHistory.instance.all(),
      builder: (context, snap) {
        if (!snap.hasData || snap.data!.isEmpty) {
          return const SizedBox.shrink(); // 履歴が無いときは非表示
        }
        final answers = snap.data!;

        // AnswerRecord -> HistoryRecord へ最小情報で変換
        final List<HistoryRecord> records = answers.map((r) {
          return HistoryRecord(
            timestamp: r.ts,
            difficulty: r.difficulty,
            domain: (r.domain ?? '未指定'),
            major: '',          // 成績パネルでは未使用のため空でOK
            mid: null,
            topic: null,
            correct: r.isCorrect,
            elapsedMs: null,
          );
        }).toList();

        // 分野別に要約 → MiniBarChart アイテムへ
        final summaries = HistoryStats.domainSummaries(records);
        if (summaries.isEmpty) return const SizedBox.shrink();
        final items = buildBarItemsFromDomainSummaries(summaries);

        return Padding(
          padding: const EdgeInsets.only(top: 12.0, bottom: 8.0),
          child: MiniBarChart(
            title: title,
            items: items.take(maxItems).toList(),
            maxItems: maxItems,
          ),
        );
      },
    );
  }
}
